publish = (args: {
    syncState: SyncState.SyncState
    payload: typeof SyncState.PayloadUpstream.Type
    materializerHashes: ReadonlyArray<LiveStoreEvent.Client.MaterializerHash>
  }) =>
    Effect.gen(function* () {
      model = { ...model, syncState: args.syncState }
      yield* SubscriptionRef.set(syncStateRef, args.syncState)
      yield* connectedSessions.offer({
        payload: args.payload,
        globalHead: args.syncState.upstreamHead,
        leaderHead: args.syncState.localHead,
        materializerHashes: args.materializerHashes,
      })
    })

callerOld:
make = Effect.fnUntraced(function* ({
  schema,
  runtime,
  initialBlockingSyncContext,
  initialSyncState,
  onError,
  onBackendIdMismatch,
  livePull,
  params,
  testing,
}: Options) {
  const dbState = yield* StateSqliteDb.StateSqliteDb
  const dbEventlog = yield* EventlogSqliteDb.EventlogSqliteDb
  // Every durable leader write (rollback, materialization, eventlog, journal and heads) goes through this seam.
  const persistence = yield* LeaderPersistence.LeaderPersistence
  const { devtoolsLatch, shutdownChannel, span, syncBackend } = runtime
  const syncBackendPushQueue = yield* TxQueue.unbounded<LiveStoreEvent.Client.Encoded>()
  const localPushBatchSize = params.localPushBatchSize ?? 10
  const backendPushBatchSize = params.backendPushBatchSize ?? 50

  const syncStateSref = yield* SubscriptionRef.make<SyncState.SyncState | undefined>(undefined)

  const isClientOnlyEvent = (eventEncoded: LiveStoreEvent.Client.Encoded) =>
    schema.eventsDefsMap.get(eventEncoded.name)?.options.clientOnly ?? false

  const connectedClientSessionPullQueues = yield* makePullQueueSet

  type LocalPushQueueItem = [
    event: LiveStoreEvent.Client.Encoded,
    deferred: Deferred.Deferred<void, LeaderAheadError | StaleRebaseGenerationError>,
  ]
  const localPushesQueue = yield* TxQueue.unbounded<LocalPushQueueItem>()
  // Reservations cover admitted pushes from validation until they are applied or rejected. The Set's
  // insertion order mirrors admission order, so its last relevant item is the optimistic sequence head.
  const reservedLocalPushItems = new Set<LocalPushQueueItem>()
  // Ensures mutual exclusion between local push and backend pull processing.
  const localPushBackendPullMutex = yield* Semaphore.make(1)
  // Serializes validation, queue admission, and prefix-fence reconciliation.
  const pushAdmissionSemaphore = yield* Semaphore.make(1)

  /**
   * Admission fence for local pushes. Unlike `syncState.localHead`, this advances as soon as an event
   * is queued, so another session cannot claim the same sequence number while that event is waiting
   * to be applied. With authoritative head e0 and reserved pushes e1/e2, this points to e2.
   *
   * All reads and writes are protected by `pushAdmissionSemaphore` so validation and reservation are
   * one atomic operation from the perspective of concurrent sessions and backend pulls.
   */
  const pushHeadRef = { current: initialSyncState.localHead }

  /**
   * A backend pull may advance or rebase authoritative history while local pushes remain reserved.
   * Keep the fence at the newest reservation that is still valid for that history; if none remains,
   * fall back to the authoritative head. Stale reservations are released later by the queue worker.
   */
  const reconcilePushHead = (authoritativeHead: EventSequenceNumber.Client.Composite) =>
    pushAdmissionSemaphore.withPermits(1)(
      Effect.gen(function* () {
        const latestCurrentGenerationItem = [...reservedLocalPushItems].findLast(
          ([event]) => event.seqNum.rebaseGeneration >= authoritativeHead.rebaseGeneration,
        )
        pushHeadRef.current = latestCurrentGenerationItem?.[0].seqNum ?? authoritativeHead
      }).pipe(Effect.uninterruptible),
    )
  /**
   * Stop completed, rejected, or stale queue items from extending the admission fence, then rebuild
   * the fence from any pushes that are still reserved.
   */
  const releasePushReservations = (
    items: ReadonlyArray<LocalPushQueueItem>,
    authoritativeHead: EventSequenceNumber.Client.Composite,
  ) =>
    pushAdmissionSemaphore.withPermits(1)(
      Effect.gen(function* () {
        for (const item of items) reservedLocalPushItems.delete(item)
        const latestCurrentGenerationItem = [...reservedLocalPushItems].findLast(
          ([event]) => event.seqNum.rebaseGeneration >= authoritativeHead.rebaseGeneration,
        )
        pushHeadRef.current = latestCurrentGenerationItem?.[0].seqNum ?? authoritativeHead
      }).pipe(Effect.uninterruptible),
    )

  const backgroundApplyLocalPushes = Effect.gen(function* () {
    while (true) {
      if (testing.delays?.localPushProcessing !== undefined) {
        yield* testing.delays.localPushProcessing.pipe(Effect.withSpan('localPushProcessingDelay'))
      }

      const batchItems = yield* TxQueue.takeBetween(localPushesQueue, 1, localPushBatchSize)

      // Applies a batch of local pushes, guarded by the localPushBackendPullMutex to ensure mutual exclusion with backend pulling
      yield* Effect.gen(function* () {
        const syncState = yield* Effect.fromNullishOr(yield* SubscriptionRef.get(syncStateSref)).pipe(
          Effect.orDieDebugger,
        )

        const currentRebaseGeneration = syncState.localHead.rebaseGeneration

        // Since the rebase generation might have changed since enqueuing, we need to filter out items with older generation
        // It's important that we filter after acquiring the localPushBackendPullMutex, otherwise we might filter with the old generation
        const [filteredItems, droppedItems] = ReadonlyArray.partition(batchItems, (batchItem) =>
          batchItem[0].seqNum.rebaseGeneration >= currentRebaseGeneration
            ? Result.succeed(batchItem)
            : Result.fail(batchItem),
        )

        if (droppedItems.length > 0) {
          yield* Effect.spanEvent(`push:drop-old-generation`, {
            droppedCount: droppedItems.length,
            currentRebaseGeneration,
          })

          yield* Effect.forEach(droppedItems, ([eventEncoded, deferred]) =>
            Deferred.fail(
              deferred,
              StaleRebaseGenerationError.make({
                currentRebaseGeneration,
                providedRebaseGeneration: eventEncoded.seqNum.rebaseGeneration,
                sessionId: eventEncoded.sessionId,
              }),
            ),
          )

          yield* releasePushReservations(droppedItems, syncState.localHead)
        }

        if (filteredItems.length === 0) {
          return
        }

        const [newEvents, deferreds] = ReadonlyArray.unzip(filteredItems)

        yield* Effect.annotateCurrentSpan({
          batchSize: newEvents.length,
          ...(TRACE_VERBOSE === true ? { newEvents: jsonStringify(newEvents) } : {}),
        })

        const mergeResult = yield* SyncState.merge({
          syncState,
          payload: { _tag: 'local-push', newEvents },
          isClientOnlyEvent,
          isEqualEvent: LiveStoreEvent.Client.isEqualEncoded,
        })

        switch (mergeResult._tag) {
          case 'rebase': {
            return yield* Effect.dieDebugger('The leader thread should never have to rebase due to a local push')
          }
          case 'reject': {
            yield* Effect.spanEvent(`push:reject`, {
              batchSize: newEvents.length,
              ...(TRACE_VERBOSE === true ? { mergeResult: jsonStringify(mergeResult) } : {}),
            })

            // TODO: how to test this?
            const nextRebaseGeneration = currentRebaseGeneration + 1

            const providedNum = newEvents.at(0)!.seqNum
            // All subsequent pushes with same generation should be rejected as well
            // We're also handling the case where the localPushQueue already contains events
            // from the next generation which we preserve in the queue
            const remainingEventsMatchingGeneration = yield* takePrefixUntil(
              localPushesQueue,
              ([eventEncoded]) => eventEncoded.seqNum.rebaseGeneration >= nextRebaseGeneration,
            )

            // TODO we still need to better understand and handle this scenario
            const remainingLocalPushes = yield* snapshotTxQueue(localPushesQueue)
            if (LS_DEV === true && remainingLocalPushes.length > 0) {
              console.log('localPushesQueue is not empty', remainingLocalPushes.length)
              // oxlint-disable-next-line no-debugger -- intentional breakpoint for unexpected queue state
              debugger
            }

            const allDeferredsToReject = [
              ...deferreds,
              ...remainingEventsMatchingGeneration.map(([_, deferred]) => deferred),
            ]

            // The rejected batch and its drained same-generation suffix will never advance leader state,
            // so release their sequence-number reservations before clients retry from the authoritative head.
            yield* releasePushReservations(
              [...filteredItems, ...remainingEventsMatchingGeneration],
              syncState.localHead,
            )

            yield* Effect.forEach(allDeferredsToReject, (deferred) =>
              Deferred.fail(
                deferred,
                LeaderAheadError.make({
                  minimumExpectedNum: mergeResult.expectedMinimumId,
                  providedNum,
                  sessionId: newEvents.at(0)!.sessionId,
                }),
              ),
            )

            // In this case we're skipping state update and down/upstream processing
            // We've cleared the local push queue and are now waiting for new local pushes / backend pulls
            return
          }
          case 'advance': {
            break
          }
          default: {
            casesHandled(mergeResult)
          }
        }

        // For a local-push advance, `newEvents` and the appended pending suffix describe the same logical
        // events but serve different roles and may be distinct instances. Materialize the retained pending
        // instances so their rollback metadata remains available if a later backend event causes a rebase.
        const acceptedPendingEvents = mergeResult.newSyncState.pending.slice(syncState.pending.length)
        if (acceptedPendingEvents.length !== mergeResult.newEvents.length) {
          return yield* Effect.dieDebugger('Local push events must be retained in pending state')
        }

        // The batch becomes durable as a whole or not at all. Everything below publishes only what the receipt reports.
        const receipt = yield* persistence.persistLocal({ events: acceptedPendingEvents })

        yield* SubscriptionRef.set(syncStateSref, mergeResult.newSyncState)

        yield* connectedClientSessionPullQueues.offer({
          payload: SyncState.PayloadUpstreamAdvance.make({ newEvents: receipt.persistedEvents }),
          globalHead: mergeResult.newSyncState.upstreamHead,
          leaderHead: mergeResult.newSyncState.localHead,
          materializerHashes: receipt.materializerHashes,
        })

        yield* Effect.spanEvent(`push:advance`, {
          batchSize: newEvents.length,
          ...(TRACE_VERBOSE === true ? { mergeResult: jsonStringify(mergeResult) } : {}),
        })

        // Don't sync client-only events
        const globalOrUnknownEvents = receipt.persistedEvents.filter((e) => !isClientOnlyEvent(e))

        yield* TxQueue.offerAll(syncBackendPushQueue, globalOrUnknownEvents)

        yield* releasePushReservations(filteredItems, mergeResult.newSyncState.localHead)

        // A push is acknowledged only after the complete batch is materialized, published in
        // leader sync state, exposed to sessions, and queued for backend propagation.
        yield* Effect.forEach(deferreds, (deferred) => Deferred.succeed(deferred, void 0))
      }).pipe(localPushBackendPullMutex.withPermits(1))
    }
  })

  const backgroundBackendPulling = Effect.fn('@livestore/common:LeaderSyncProcessor:backend-pulling')(function* ({
    restartBackendPushing,
    onPullSuccess,
  }: {
    restartBackendPushing: (
      filteredRebasedPending: ReadonlyArray<LiveStoreEvent.Client.Encoded>,
    ) => Effect.Effect<void, never, HttpClient.HttpClient>
    onPullSuccess: () => void
  }) {
    if (syncBackend === undefined) return

    let pullMutexHeld = false

    const releasePullMutexIfHeld = Effect.gen(function* () {
      if (pullMutexHeld === false) return
      pullMutexHeld = false
      yield* localPushBackendPullMutex.release(1)
    })

    const isPullPaginationComplete = (pageInfo: SyncBackend.PullResPageInfo) => pageInfo._tag === 'NoMore'

    const onNewPullChunk = (
      pulledEvents: ReadonlyArray<LeaderPersistence.PulledEvent>,
      pageInfo: SyncBackend.PullResPageInfo,
    ) =>
      Effect.gen(function* () {
        const newEvents = pulledEvents.map(({ event }) => event)

        if (devtoolsLatch !== undefined) {
          yield* devtoolsLatch.await
        }

        if (newEvents.length === 0) {
          if (isPullPaginationComplete(pageInfo) === true) {
            yield* releasePullMutexIfHeld
          }
          return
        }

        // Prevent more local pushes from being processed until this pull pagination sequence is finished.
        if (pullMutexHeld === false) {
          yield* localPushBackendPullMutex.take(1)
          pullMutexHeld = true
        }

        const chunkExit = yield* Effect.gen(function* () {
          const syncState = yield* Effect.fromNullishOr(yield* SubscriptionRef.get(syncStateSref)).pipe(
            Effect.orDieDebugger,
          )

          yield* Effect.annotateCurrentSpan({
            'merge.newEventsCount': newEvents.length,
            ...(TRACE_VERBOSE === true ? { 'merge.newEvents': jsonStringify(newEvents) } : {}),
          })

          const mergeResult = yield* SyncState.merge({
            syncState,
            payload: SyncState.PayloadUpstreamAdvance.make({ newEvents }),
            isClientOnlyEvent,
            isEqualEvent: LiveStoreEvent.Client.isEqualEncoded,
            ignoreClientOnlyEvents: true,
          })

          if (mergeResult._tag === 'reject') {
            return yield* Effect.dieDebugger('The leader thread should never reject upstream advances')
          }

          const newBackendHead = newEvents.at(-1)!.seqNum
          const rollbackEvents = mergeResult._tag === 'rebase' ? mergeResult.rollbackEvents : []

          // Rollback, materialization, confirmation metadata, journal pruning and the backend head commit together,
          // so readers cannot observe a leader head whose events are not durable. Everything below publishes only
          // what the receipt reports; sessions need its materializer hashes for these events.
          const receipt = yield* persistence.persistUpstream({
            pulledEvents,
            events: mergeResult.newEvents,
            rollbackEvents,
            confirmedEvents: mergeResult._tag === 'advance' ? mergeResult.confirmedEvents : [],
            backendHead: newBackendHead,
          })

          if (mergeResult._tag === 'rebase') {
            yield* Effect.spanEvent(`pull:rebase[${mergeResult.newSyncState.localHead.rebaseGeneration}]`, {
              newEventsCount: newEvents.length,
              ...(TRACE_VERBOSE === true ? { newEvents: jsonStringify(newEvents) } : {}),
              rollbackCount: rollbackEvents.length,
              ...(TRACE_VERBOSE === true ? { mergeResult: jsonStringify(mergeResult) } : {}),
            })
          } else {
            yield* Effect.spanEvent(`pull:advance`, {
              newEventsCount: newEvents.length,
              ...(TRACE_VERBOSE === true ? { mergeResult: jsonStringify(mergeResult) } : {}),
            })
          }

          // Restart the push fiber with the current pending (non-client-only) events. After a rebase these are the
          // rebased events; after an advance this ensures the push fiber is active again.
          yield* restartBackendPushing(mergeResult.newSyncState.pending.filter((e) => !isClientOnlyEvent(e)))

          // The backend merge may advance or rebase the authoritative head. Realign the admission
          // fence now so newly arriving pushes are validated against that history, not the pre-pull head.
          yield* reconcilePushHead(mergeResult.newSyncState.localHead)

          yield* connectedClientSessionPullQueues.offer({
            payload:
              mergeResult._tag === 'rebase'
                ? SyncState.PayloadUpstreamRebase.make({ rollbackEvents, newEvents: receipt.persistedEvents })
                : SyncState.PayloadUpstreamAdvance.make({ newEvents: receipt.persistedEvents }),
            globalHead: mergeResult.newSyncState.upstreamHead,
            leaderHead: mergeResult.newSyncState.localHead,
            materializerHashes: receipt.materializerHashes,
          })

          yield* SubscriptionRef.set(syncStateSref, mergeResult.newSyncState)
        }).pipe(Effect.exit)

        if (Exit.isFailure(chunkExit) === true) {
          yield* releasePullMutexIfHeld
          return yield* Effect.failCause(chunkExit.cause)
        }

        if (isPullPaginationComplete(pageInfo) === true) {
          yield* releasePullMutexIfHeld
        }
      })

    const syncState = yield* Effect.fromNullishOr(yield* SubscriptionRef.get(syncStateSref)).pipe(Effect.orDieDebugger)
    const cursorInfo = yield* Eventlog.getSyncBackendCursorInfoForDb(dbEventlog, {
      remoteHead: syncState.upstreamHead.global,
    })

    yield* syncBackend.pull(cursorInfo, { live: livePull }).pipe(
      // TODO only take from queue while connected
      Stream.tap(({ batch, pageInfo }) =>
        Effect.gen(function* () {
          // Any response (including an empty batch) proves backend contact, even with stale connectivity.
          onPullSuccess()
          // NOTE we only want to take process events when the sync backend is connected
          // (e.g. needed for simulating being offline)
          // TODO remove when there's a better way to handle this in stream above
          yield* SubscriptionRef.waitUntil(syncBackend.isConnected, (isConnected) => isConnected === true)
          yield* onNewPullChunk(
            batch.map((item) => ({
              event: LiveStoreEvent.Client.fromGlobal(item.eventEncoded),
              syncMetadata: item.metadata,
            })),
            pageInfo,
          )
          yield* initialBlockingSyncContext.update({ processed: batch.length, pageInfo })
        }),
      ),
      Stream.runDrain,
      Effect.interruptible,
      Effect.ensuring(releasePullMutexIfHeld),
    )

    // Should only ever happen when livePull is false
    yield* Effect.logDebug('backend-pulling finished', { livePull })
  })

  const backgroundBackendPushing = Effect.gen(function* () {
    if (syncBackend === undefined) return

    while (true) {
      yield* SubscriptionRef.waitUntil(syncBackend.isConnected, (isConnected) => isConnected === true)

      const queueItems = yield* TxQueue.takeBetween(syncBackendPushQueue, 1, backendPushBatchSize)

      yield* SubscriptionRef.waitUntil(syncBackend.isConnected, (isConnected) => isConnected === true)

      if (devtoolsLatch !== undefined) {
        yield* devtoolsLatch.await
      }

      yield* Effect.spanEvent('backend-push', {
        batchSize: queueItems.length,
        ...(TRACE_VERBOSE === true ? { batch: jsonStringify(queueItems) } : {}),
      })

      // Push with declarative retry/backoff using Effect schedules
      // - Exponential backoff starting at 1s and doubling (1s, 2s, 4s, 8s, 16s, 30s ...)
      // - Delay clamped at 30s (continues retrying at 30s)
      // - Resets automatically after successful push
      // TODO(metrics): expose counters/gauges for retry attempts and queue health via devtools/metrics
      yield* Effect.gen(function* () {
        const iteration = yield* Schedule.CurrentMetadata

        const pushResult = yield* syncBackend.push(queueItems.map(LiveStoreEvent.Client.toGlobal)).pipe(Effect.result)

        const retries = iteration.attempt
        if (retries > 0 && Result.isSuccess(pushResult) === true) {
          yield* Effect.spanEvent('backend-push-retry-success', { retries, batchSize: queueItems.length })
        }

        if (Result.isFailure(pushResult) === true) {
          yield* Effect.spanEvent('backend-push-error', {
            error: pushResult.failure.toString(),
            retries,
            batchSize: queueItems.length,
          })
          const error = pushResult.failure
          if (error._tag === 'ServerAheadError') {
            // It's a core part of the sync protocol that the sync backend will emit a new pull chunk alongside the ServerAheadError
            yield* Effect.logDebug('handled backend-push-error (waiting for interupt caused by pull)', { error })
            return yield* Effect.never
          }

          return yield* error
        }
      }).pipe(
        // Retry transient errors
        Effect.retry({
          schedule: Schedule.exponential(Duration.seconds(1)).pipe(
            Schedule.modifyDelay(({ duration }) => Effect.succeed(Duration.min(duration, Duration.seconds(30)))), // Cap delay at 30s intervals.
          ),
          while: (error) => error._tag === 'IsOfflineError' || error._tag === 'UnknownError',
        }),
        // This is needed to narrow the Error type. Our retry policy runs indefinitely, but Effect.retry does not narrow the Error type.
        Effect.catchIf((error) => error._tag === 'IsOfflineError' || error._tag === 'UnknownError', Effect.die),
      )
    }
  }).pipe(Effect.interruptible)

  // NOTE: New events are only pushed to sync backend after successful local push processing
  const push: Service['push'] = (newEvents) =>
    Effect.gen(function* () {
      if (newEvents.length === 0) return

      const deferreds = yield* Effect.forEach(newEvents, () =>
        Deferred.make<void, LeaderAheadError | StaleRebaseGenerationError>(),
      )

      const items = newEvents.map((eventEncoded, i) => [eventEncoded, deferreds[i]] as LocalPushQueueItem)

      // Validation, reservation, enqueueing, and fence advancement form one admission transaction.
      // Serializing them prevents concurrent sessions from both validating against the same head and
      // prevents backend reconciliation from changing the fence midway through admission.
      yield* pushAdmissionSemaphore.withPermits(1)(
        // Cancellation must not leave reservations, queue contents, and the admission fence disagreeing.
        Effect.gen(function* () {
          yield* validatePushBatch(newEvents, pushHeadRef.current, isClientOnlyEvent)
          for (const item of items) reservedLocalPushItems.add(item)
          yield* TxQueue.offerAll(localPushesQueue, items)
          pushHeadRef.current = newEvents.at(-1)!.seqNum
          if (testing.hooks?.localPushAdmitted !== undefined) {
            yield* testing.hooks.localPushAdmitted(newEvents)
          }
        }).pipe(Effect.uninterruptible),
      )

      yield* Effect.forEach(deferreds, Deferred.await)
    }).pipe(
      Effect.withSpan('@livestore/common:LeaderSyncProcessor:push', {
        attributes: {
          batchSize: newEvents.length,
          batch: TRACE_VERBOSE === true ? newEvents : undefined,
        },
        links: span !== undefined ? [{ span, attributes: {} }] : undefined,
      }),
    )

  return LeaderSyncProcessor.of({
    [TypeId]: TypeId,
    // Starts various background loops
    boot: Effect.gen(function* () {
      /** State transitions need to happen atomically, so we use a Ref to track the state */
      yield* SubscriptionRef.set(syncStateSref, initialSyncState)

      // Rehydrate sync queue
      if (initialSyncState.pending.length > 0) {
        const globalOrUnknownPendingEvents = initialSyncState.pending
          // Don't sync client-only events
          .filter((eventEncoded) => !isClientOnlyEvent(eventEncoded))

        if (globalOrUnknownPendingEvents.length > 0) {
          yield* TxQueue.offerAll(syncBackendPushQueue, globalOrUnknownPendingEvents)
        }
      }

      const handleBackendIdMismatchError = (error: BackendIdMismatchError) =>
        handleBackendIdMismatch({ error, onBackendIdMismatch, shutdownChannel, dbEventlog, dbState })

      const maybeShutdownOnError = (
        cause: Cause.Cause<UnknownError | MaterializeError | MaterializationJournal.MaterializationJournalError>,
      ) =>
        Effect.gen(function* () {
          if (onError === 'ignore') {
            if (LS_DEV === true) {
              yield* Effect.logDebug(
                `Ignoring sync error (${Option.getOrUndefined(Cause.findErrorOption(cause))?._tag ?? cause.toString()})`,
                Cause.pretty(cause),
              )
            }
            return
          }

          const error = Option.getOrUndefined(Cause.findErrorOption(cause))
          const errorToSend = error === undefined ? UnknownError.make({ cause }) : error
          yield* shutdownChannel.send(errorToSend).pipe(Effect.orDie)

          return yield* Effect.failCause(cause).pipe(Effect.orDie)
        })

      yield* backgroundApplyLocalPushes.pipe(Effect.catchCause(maybeShutdownOnError), Effect.forkScoped)

      const backendPushingFiberHandle = yield* FiberHandle.make<void, never>()
      const backendPushingEffect = backgroundBackendPushing.pipe(
        Effect.catchTag('BackendIdMismatchError', handleBackendIdMismatchError),
        Effect.catchCause(maybeShutdownOnError),
      )

      yield* FiberHandle.run(backendPushingFiberHandle, backendPushingEffect)

      let offlinePullFallbackMs = 1_000

      yield* backgroundBackendPulling({
        onPullSuccess: () => {
          offlinePullFallbackMs = 1_000
        },
        restartBackendPushing: (filteredRebasedPending) =>
          Effect.gen(function* () {
            // Stop current pushing fiber
            yield* FiberHandle.clear(backendPushingFiberHandle)

            // Reset the sync backend push queue
            yield* TxQueue.clear(syncBackendPushQueue)
            yield* TxQueue.offerAll(syncBackendPushQueue, filteredRebasedPending)

            // Restart pushing fiber
            yield* FiberHandle.run(backendPushingFiberHandle, backendPushingEffect)
          }),
      }).pipe(
        Effect.tapError((error) => {
          if (error._tag !== 'IsOfflineError' || syncBackend === undefined) return Effect.void
          const isConnected = syncBackend.isConnected
          return Effect.gen(function* () {
            // Wake immediately on reconnection. Probe on a capped fallback timer if connectivity is stale.
            const jitter = yield* Random.nextBetween(0.8, 1.2)
            const fallbackMs =
              testing.delays?.backendPullReconnect?.(offlinePullFallbackMs * jitter) ?? offlinePullFallbackMs * jitter
            offlinePullFallbackMs = Math.min(offlinePullFallbackMs * 2, 30_000)
            // A stale initial true is not a reconnect. Watch false→true even while the fallback timer is pending.
            const waitHook = testing.hooks?.backendPullReconnectWait
            const changes = SubscriptionRef.changes(isConnected)
            const observedChanges =
              waitHook === undefined
                ? changes
                : changes.pipe(Stream.tap((value) => waitHook({ isConnected: value, fallbackMs })))
            const reconnected = yield* observedChanges.pipe(
              Stream.dropWhile((value) => value === true),
              Stream.filter((value) => value === true),
              Stream.runHead,
              Effect.as(true),
              Effect.timeoutOrElse({ duration: fallbackMs, orElse: () => Effect.succeed(false) }),
            )
            if (reconnected === true) offlinePullFallbackMs = 1_000
          })
        }),
        Effect.retry({
          // The unbounded offline-only retry keeps IsOfflineError out of the terminal error channel.
          until: (error): error is Exclude<typeof error, IsOfflineError> => error._tag !== 'IsOfflineError',
        }),
        Effect.catchTag('BackendIdMismatchError', handleBackendIdMismatchError),
        Effect.catchCause(maybeShutdownOnError),
        // Needed to avoid `Fiber terminated with an unhandled error` logs which seem to happen because of the `Effect.retry` above.
        // This might be a bug in Effect. Only seems to happen in the browser.
        Effect.provideService(References.UnhandledLogLevel, undefined),
        Effect.forkScoped,
      )

      return { initialLeaderHead: initialSyncState.localHead }
    }).pipe(Effect.withSpanScoped('@livestore/common:LeaderSyncProcessor:boot')),
    push,
    pushPartial: ({ event: { name, args }, clientId, sessionId }) =>
      Effect.gen(function* () {
        const syncState = yield* Effect.fromNullishOr(yield* SubscriptionRef.get(syncStateSref)).pipe(
          Effect.orDieDebugger,
        )

        const resolution = yield* resolveEventDef(schema, {
          operation: '@livestore/common:LeaderSyncProcessor:pushPartial',
          event: {
            name,
            args,
            clientId,
            sessionId,
            seqNum: syncState.localHead,
          },
        })

        if (resolution._tag === 'unknown') {
          // Ignore partial pushes for unrecognised events – they are still
          // persisted server-side once a schema update ships.
          return
        }

        const eventEncoded = LiveStoreEvent.Client.Encoded.make({
          name,
          args,
          clientId,
          sessionId,
          ...EventSequenceNumber.Client.nextPair({
            seqNum: syncState.localHead,
            isClientOnly: resolution.eventDef.options.clientOnly,
          }),
        })

        yield* push([eventEncoded])
      }).pipe(
        // pushPartial constructs the event sequence number internally, so these errors should never happen.
        Effect.catchIf(isRejectedPushError, Effect.die),
      ),
    pull: ({ cursor }) =>
      Effect.gen(function* () {
        const queue = yield* connectedClientSessionPullQueues.makeQueue(cursor)
        return Stream.fromQueue(queue)
      }).pipe(Stream.unwrap),
    /*
      Notes for a potential new `LeaderSyncProcessor.pull` implementation:

      - Doesn't take cursor but is "atomically called" in the leader during the snapshot phase
        - TODO: how is this done "atomically" in the web adapter where the snapshot is read optimistically?
      - Would require a new kind of "boot-phase" API which is stream based:
        - initial message: state snapshot + seq num head
        - subsequent messages: sync state payloads

      - alternative: instead of session pulling sync state payloads from leader, we could send
        - events in the "advance" case
        - full new state db snapshot in the "rebase" case
          - downside: importing the snapshot is expensive
      */
    pullQueue: ({ cursor }) => connectedClientSessionPullQueues.makeQueue(cursor),
    syncState: Subscribable.make({
      get: SubscriptionRef.get(syncStateSref).pipe(Effect.flatMap(Effect.fromNullishOr), Effect.orDieDebugger),
      changes: SubscriptionRef.changes(syncStateSref).pipe(Stream.filter(Predicate.isNotUndefined)),
    }),
  })
})

callerNew:
make = Effect.fnUntraced(function* ({
  schema,
  runtime,
  initialBlockingSyncContext,
  initialSyncState,
  onError,
  onBackendIdMismatch,
  livePull,
  params,
  testing,
}: Options) {
  const dbEventlog = yield* EventlogSqliteDb.EventlogSqliteDb
  const dbState = yield* StateSqliteDb.StateSqliteDb
  const persistence = yield* LeaderPersistence.LeaderPersistence
  const { devtoolsLatch, shutdownChannel, span, syncBackend } = runtime

  const mailbox = yield* Queue.unbounded<LeaderMessage>()
  const syncStateRef = yield* SubscriptionRef.make(initialSyncState)
  const connectedSessions = yield* makePullQueueSet
  const bootDeferred = yield* Deferred.make<EventSequenceNumber.Client.Composite>()
  const startedDeferred = yield* Deferred.make<void>()
  const stoppedDeferred = yield* Deferred.make<void>()
  const nextLocalRequestId = yield* Ref.make(1)
  const nextPullBatchId = yield* Ref.make(1)
  const localRequests = yield* Ref.make<LocalRequestRegistry>({ _tag: 'open', requests: new Map() })
  const pullBatches = yield* Ref.make(new Map<PullBatchId, Deferred.Deferred<void>>())
  const bootStarted = yield* Ref.make(false)
  const pushHandle = yield* FiberHandle.make<void, never>()
  const pullHandle = yield* FiberHandle.make<void, never>()
  const backgroundFibers = yield* FiberSet.make<void, never>()

  const config: Config = {
    livePull,
    localCommitBatchSize: params.localPushBatchSize ?? 10,
    backendPushBatchSize: params.backendPushBatchSize ?? 50,
    onError,
    onBackendIdMismatch,
    localWorkInitiallyBlocked: testing.delays?.localPushProcessing !== undefined,
  }
  const isClientOnlyEvent = (event: LiveStoreEvent.Client.Encoded) =>
    schema.eventsDefsMap.get(event.name)?.options.clientOnly ?? false
  // `model` is intentionally local rather than a Ref. Only the mailbox loop changes it, apart from boot and
  // operation startup which also run in this scope before their asynchronous work reports back through the mailbox.
  let model = initialModel(config, syncBackend !== undefined, initialSyncState, isClientOnlyEvent)

  const send = (message: LeaderMessage) => Queue.offer(mailbox, message).pipe(Effect.asVoid)
  const fork = (effect: Effect.Effect<void>) => FiberSet.run(backgroundFibers, effect).pipe(Effect.asVoid)
  const allocateOperationId = () => {
    // Completion messages carry this id so a late result from an interrupted provider call cannot affect newer work.
    const operationId = model.nextOperationId
    model = { ...model, nextOperationId: operationId + 1 }
    return operationId
  }

  const interruptAllWork = Effect.all([
    FiberHandle.clear(pushHandle),
    FiberHandle.clear(pullHandle),
    FiberSet.clear(backgroundFibers),
    interruptAllLocalRequests(localRequests),
    interruptAllPullBatches(pullBatches),
  ])

  const stop = (args: {
    readonly lifecycle: 'stopping' | 'failed'
    readonly error?: unknown
    readonly notify: boolean
  }) =>
    Effect.gen(function* () {
      if ((yield* Deferred.isDone(stoppedDeferred)) === true) return false
      model = { ...model, lifecycle: args.lifecycle }
      if (args.notify === true && args.error !== undefined) {
        // A broken shutdown channel must not prevent resource cleanup or leave admitted pushes unresolved.
        yield* shutdownChannel
          .send(
            Schema.is(Shutdown.All)(args.error) === true
              ? args.error
              : UnknownError.make({ cause: args.error, note: 'Leader sync loop failed' }),
          )
          .pipe(Effect.exit)
      }
      yield* interruptAllWork
      yield* Deferred.succeed(stoppedDeferred, void 0)
      return false
    })

  const stopForSyncFailure = (cause: unknown) =>
    stop({ lifecycle: 'failed', error: cause, notify: config.onError === 'shutdown' })

  const startProviderPush = () =>
    Effect.gen(function* () {
      if (model.lifecycle !== 'running' || model.push._tag !== 'idle') return
      if (model.push.queued.length === 0) return
      const batch = model.push.queued.slice(0, config.backendPushBatchSize)
      yield* runPushOperation({ attempt: 0, batch, queued: model.push.queued.slice(batch.length) })
    })

  /** Starts a provider push for `batch`. A retry reuses it with the attempt count of the failed operation. */
  const runPushOperation = (push: { attempt: number; batch: EventBatch; queued: EventBatch }) =>
    Effect.gen(function* () {
      if (syncBackend === undefined) return
      const operationId = allocateOperationId()
      model = {
        ...model,
        push: { _tag: 'in-flight', operationId, attempt: push.attempt, batch: push.batch, queued: push.queued },
      }
      yield* FiberHandle.run(
        pushHandle,
        runProviderPush({ operationId, attempt: push.attempt, batch: push.batch }, syncBackend, devtoolsLatch, send),
      ).pipe(Effect.asVoid)
    })

  const startProviderPull = (attempt: number) =>
    Effect.gen(function* () {
      if (syncBackend === undefined || model.lifecycle !== 'running') return
      const pullId = allocateOperationId()
      model = { ...model, pull: { _tag: 'streaming', pullId, pagination: 'between-pages', attempt } }
      yield* FiberHandle.run(
        pullHandle,
        runProviderPull({
          pullId,
          cursor: model.syncState.upstreamHead,
          live: config.livePull,
          syncBackend,
          devtoolsLatch,
          dbEventlog,
          pullBatches,
          nextPullBatchId,
          initialBlockingSyncContext,
          send,
        }),
      ).pipe(Effect.asVoid)
    })

  const replacePushPlan = (replacement: ReadonlyArray<LiveStoreEvent.Client.Encoded>) =>
    Effect.gen(function* () {
      if (model.push._tag === 'disabled') return
      const inFlight = model.push._tag === 'in-flight'
      // An upstream rebase may have changed every pending sequence number. Rebuild the provider queue from the
      // committed sync state instead of trying to patch the old plan.
      model = { ...model, push: { _tag: 'idle', queued: replacement } }
      if (inFlight === true) yield* FiberHandle.clear(pushHandle)
      yield* startProviderPush()
    })

  const publish = (args: {
    syncState: SyncState.SyncState
    payload: typeof SyncState.PayloadUpstream.Type
    materializerHashes: ReadonlyArray<LiveStoreEvent.Client.MaterializerHash>
  }) =>
    Effect.gen(function* () {
      model = { ...model, syncState: args.syncState }
      yield* SubscriptionRef.set(syncStateRef, args.syncState)
      yield* connectedSessions.offer({
        payload: args.payload,
        globalHead: args.syncState.upstreamHead,
        leaderHead: args.syncState.localHead,
        materializerHashes: args.materializerHashes,
      })
    })

  const processLocalBatch = (items: ReadonlyArray<LocalItem>) =>
    Effect.gen(function* () {
      const mergeExit = yield* SyncState.merge({
        syncState: model.syncState,
        payload: { _tag: 'local-push', newEvents: items.map((item) => item.event) },
        isClientOnlyEvent,
        isEqualEvent: LiveStoreEvent.Client.isEqualEncoded,
      }).pipe(Effect.exit)
      if (Exit.isFailure(mergeExit) === true) return yield* stopForSyncFailure(Cause.squash(mergeExit.cause))
      const merge = mergeExit.value
      if (merge._tag === 'reject') {
        // Later events in the same generation were numbered on top of this rejected batch, so they cannot remain
        // valid on their own. Reject them together and let the session produce a fresh sequence.
        const generation = items[0]?.event.seqNum.rebaseGeneration
        const queuedSameGeneration = model.localQueue.filter(
          (item) => item.event.seqNum.rebaseGeneration === generation,
        )
        const rejectedItems = [...items, ...queuedSameGeneration]
        const rejectedKeys = new Set(rejectedItems.map(localItemKey))
        const firstEvent = items[0]?.event
        model = {
          ...model,
          localQueue: model.localQueue.filter((item) => !rejectedKeys.has(localItemKey(item))),
        }
        if (firstEvent !== undefined) {
          const error = new LeaderAheadError({
            minimumExpectedNum: merge.expectedMinimumId,
            providedNum: firstEvent.seqNum,
            sessionId: firstEvent.sessionId,
          })
          yield* rejectLocalItems(
            localRequests,
            rejectedItems.map((item) => ({ item, error })),
          )
        }
        yield* send({ _tag: 'ContinueWork' })
        return true
      }
      if (merge._tag === 'rebase') return yield* stopForSyncFailure(new Error('Local push required rebase'))

      // Commit the events retained by the merge, not the input objects. This is the proposed state transition that
      // LeaderPersistence must either make durable as a whole or reject.
      const events = merge.newSyncState.pending.slice(model.syncState.pending.length)
      if (events.length !== merge.newEvents.length) {
        return yield* stopForSyncFailure(new Error('Local push was not retained as pending'))
      }
      const persistExit = yield* persistence.persistLocal({ events }).pipe(Effect.exit)
      if (Exit.isFailure(persistExit) === true) return yield* stopForSyncFailure(Cause.squash(persistExit.cause))
      const receipt = persistExit.value
      if (EventSequenceNumber.Client.isEqual(receipt.stateHead, merge.newSyncState.localHead) === false) {
        return yield* stopForSyncFailure({
          _tag: 'PersistReceiptMismatch',
          expectedStateHead: merge.newSyncState.localHead,
          receipt,
        })
      }

      yield* publish({
        syncState: merge.newSyncState,
        payload: SyncState.PayloadUpstreamAdvance.make({ newEvents: receipt.persistedEvents }),
        materializerHashes: receipt.materializerHashes,
      })
      model = enqueuePushEvents(
        model,
        receipt.persistedEvents.filter((event) => !isClientOnlyEvent(event)),
      )
      yield* startProviderPush()
      yield* completeLocalItems(localRequests, items)
      yield* send({ _tag: 'ContinueWork' })
      return true
    })

  const processUpstreamBatch = (batch: UpstreamBatch) =>
    Effect.gen(function* () {
      const mergeExit = yield* SyncState.merge({
        syncState: model.syncState,
        payload: SyncState.PayloadUpstreamAdvance.make({ newEvents: batch.events }),
        isClientOnlyEvent,
        isEqualEvent: LiveStoreEvent.Client.isEqualEncoded,
        ignoreClientOnlyEvents: true,
      }).pipe(Effect.exit)
      if (Exit.isFailure(mergeExit) === true) return yield* stopForSyncFailure(Cause.squash(mergeExit.cause))
      const merge = mergeExit.value
      if (merge._tag === 'reject') return yield* stopForSyncFailure(new Error('Upstream batch rejected'))

      const rollbackEvents = merge._tag === 'rebase' ? merge.rollbackEvents : []
      const confirmedEvents = merge._tag === 'advance' ? merge.confirmedEvents : []
      const backendHead = batch.events.at(-1)?.seqNum
      if (backendHead === undefined) return yield* stopForSyncFailure(new Error('Upstream batch has no head'))
      const persistExit = yield* persistence
        .persistUpstream({
          pulledEvents: batch.pulledEvents,
          events: merge.newEvents,
          rollbackEvents,
          confirmedEvents,
          backendHead,
        })
        .pipe(Effect.exit)
      if (Exit.isFailure(persistExit) === true) return yield* stopForSyncFailure(Cause.squash(persistExit.cause))
      const receipt = persistExit.value
      // The backend reports confirmed events without their local rebase generation, so confirming a pending event
      // that was rebased locally leaves the persisted state head at the same DAG position with a higher generation.
      if (
        LeaderPersistence.isSameSequencePosition(receipt.stateHead, merge.newSyncState.localHead) === false ||
        EventSequenceNumber.Client.isEqual(receipt.backendHead, backendHead) === false
      ) {
        return yield* stopForSyncFailure({
          _tag: 'PersistReceiptMismatch',
          expectedStateHead: merge.newSyncState.localHead,
          expectedBackendHead: backendHead,
          receipt,
        })
      }

      const payload =
        merge._tag === 'rebase'
          ? SyncState.PayloadUpstreamRebase.make({ rollbackEvents, newEvents: receipt.persistedEvents })
          : SyncState.PayloadUpstreamAdvance.make({ newEvents: receipt.persistedEvents })
      yield* publish({ syncState: merge.newSyncState, payload, materializerHashes: receipt.materializerHashes })
      yield* completePullBatch(pullBatches, batch.batchId)
      yield* replacePushPlan(merge.newSyncState.pending.filter((event) => !isClientOnlyEvent(event)))
      yield* send({ _tag: 'ContinueWork' })
      return true
    })

  const processNextWork = () =>
    Effect.gen(function* () {
      if (model.lifecycle !== 'running') return true
      // Apply backend truth before more local work. This avoids assigning local events on top of a head that is
      // already known to need an upstream advance or rebase.
      const [upstream, ...remainingUpstream] = model.upstreamQueue
      if (upstream !== undefined) {
        model = { ...model, upstreamQueue: remainingUpstream }
        return yield* processUpstreamBatch(upstream)
      }
      // When a backend page says another page follows, keep local work paused until that page arrives. Together the
      // pages describe one uninterrupted upstream advance.
      if (model.pull._tag === 'streaming' && model.pull.pagination === 'more-expected') return true
      if (model.localWorkEnabled === false || model.localQueue.length === 0) return true

      const selected = model.localQueue.slice(0, config.localCommitBatchSize)
      const selectedKeys = new Set(selected.map(localItemKey))
      const remaining = model.localQueue.filter((item) => !selectedKeys.has(localItemKey(item)))
      const currentGeneration = model.syncState.localHead.rebaseGeneration
      const staleItems = selected.filter((item) => item.event.seqNum.rebaseGeneration < currentGeneration)
      const activeItems = selected.filter((item) => item.event.seqNum.rebaseGeneration >= currentGeneration)
      model = { ...model, localQueue: remaining }
      if (staleItems.length > 0) {
        model = { ...model, localQueue: [...activeItems, ...remaining] }
        yield* rejectLocalItems(
          localRequests,
          staleItems.map((item) => ({
            item,
            error: new StaleRebaseGenerationError({
              currentRebaseGeneration: currentGeneration,
              providedRebaseGeneration: item.event.seqNum.rebaseGeneration,
              sessionId: item.event.sessionId,
            }),
          })),
        )
        yield* send({ _tag: 'ContinueWork' })
        return true
      }
      return yield* processLocalBatch(activeItems)
    })

  const handleBackendMismatch = (error: BackendIdMismatchError, direction: 'pull' | 'push') =>
    Effect.gen(function* () {
      switch (config.onBackendIdMismatch) {
        case 'ignore':
          model = {
            ...model,
            ...(direction === 'pull'
              ? { pull: { _tag: 'completed' } as const }
              : { push: { _tag: 'disabled' } as const }),
          }
          if (direction === 'pull') yield* send({ _tag: 'ContinueWork' })
          return true
        case 'shutdown':
          yield* Effect.logWarning(
            'Sync backend identity changed (backend was reset). Shutting down without clearing local storage.',
            error,
          )
          return yield* stop({ lifecycle: 'failed', error, notify: true })
        case 'reset': {
          yield* Effect.logWarning(
            'Sync backend identity changed (backend was reset). Clearing local storage and shutting down.',
            error,
          )
          // Stop all work that could still touch the databases before clearing them.
          model = { ...model, lifecycle: 'stopping' }
          yield* interruptAllWork
          const resetExit = yield* clearLocalDatabases({ dbEventlog, dbState }).pipe(Effect.exit)
          const cause =
            Exit.isFailure(resetExit) === true
              ? Cause.squash(resetExit.cause)
              : IntentionalShutdownCause.make({ reason: 'backend-id-mismatch' })
          return yield* stop({ lifecycle: 'failed', error: cause, notify: true })
        }
        default:
          return casesHandled(config.onBackendIdMismatch)
      }
    }).pipe(Effect.withSpan('@livestore/common:LeaderSyncProcessor:handleBackendIdMismatch'))

  const handleMessage = (message: LeaderMessage): Effect.Effect<boolean> =>
    Effect.gen(function* () {
      if (message._tag === 'ShutdownRequested') {
        return yield* stop({ lifecycle: 'stopping', notify: false })
      }
      if (model.lifecycle !== 'running') {
        if (message._tag === 'LocalPushRequested') yield* interruptLocalRequests(localRequests, [message.requestId])
        return true
      }

      switch (message._tag) {
        case 'LocalPushRequested': {
          // The local queue holds admitted but not-yet-committed events. Validating against its tail prevents two
          // callers from being admitted with the same sequence number while they wait in the queue.
          const pushHead = model.localQueue.at(-1)?.event.seqNum ?? model.syncState.localHead
          const validation = yield* validatePushBatch(message.events, pushHead, isClientOnlyEvent).pipe(Effect.result)
          const items = message.events.map((pushedEvent, index) => ({
            requestId: message.requestId,
            index,
            event: pushedEvent,
          }))
          if (Result.isFailure(validation) === true) {
            yield* rejectLocalItems(
              localRequests,
              items.map((item) => ({ item, error: validation.failure })),
            )
            return true
          }
          model = { ...model, localQueue: [...model.localQueue, ...items] }
          yield* testing.hooks?.localPushAdmitted?.(message.events) ?? Effect.void
          yield* send({ _tag: 'ContinueWork' })
          return true
        }
        case 'LocalWorkEnabled':
          model = { ...model, localWorkEnabled: true }
          yield* send({ _tag: 'ContinueWork' })
          return true
        case 'ContinueWork':
          return yield* processNextWork()
        case 'UpstreamBatchReceived': {
          if (model.pull._tag !== 'streaming' || model.pull.pullId !== message.batch.pullId) {
            // The provider fiber waits for every page to be released. Even a late page from an old pull must be
            // released, although it must not change the current model.
            yield* completePullBatch(pullBatches, message.batch.batchId)
            return true
          }
          if (message.batch.events.length === 0) {
            if (message.batch.pageInfo._tag === 'NoMore') {
              model = { ...model, pull: { ...model.pull, pagination: 'between-pages' } }
            }
            yield* completePullBatch(pullBatches, message.batch.batchId)
            yield* send({ _tag: 'ContinueWork' })
            return true
          }
          model = {
            ...model,
            pull: {
              ...model.pull,
              pagination: message.batch.pageInfo._tag === 'NoMore' ? 'between-pages' : 'more-expected',
            },
            upstreamQueue: [...model.upstreamQueue, message.batch],
          }
          yield* send({ _tag: 'ContinueWork' })
          return true
        }
        case 'PullCompleted':
          if (model.pull._tag === 'streaming' && model.pull.pullId === message.pullId) {
            model = { ...model, pull: { _tag: 'completed' } }
            yield* send({ _tag: 'ContinueWork' })
          }
          return true
        case 'PullFailed':
          if (model.pull._tag !== 'streaming' || model.pull.pullId !== message.pullId) return true
          if (message.error._tag === 'IsOfflineError') {
            const retryId = allocateOperationId()
            const attempt = model.pull.attempt + 1
            model = { ...model, pull: { _tag: 'retry-wait', retryId, attempt } }
            yield* fork(
              Effect.sleep(Duration.millis(retryDelay(attempt))).pipe(
                Effect.andThen(send({ _tag: 'PullRetryElapsed', retryId })),
              ),
            )
            return true
          }
          if (message.error._tag === 'BackendIdMismatchError')
            return yield* handleBackendMismatch(message.error, 'pull')
          if (config.onError === 'shutdown')
            return yield* stop({ lifecycle: 'failed', error: message.error, notify: true })
          model = { ...model, pull: { _tag: 'completed' } }
          yield* send({ _tag: 'ContinueWork' })
          return true
        case 'PullRetryElapsed':
          if (model.pull._tag === 'retry-wait' && model.pull.retryId === message.retryId) {
            yield* startProviderPull(model.pull.attempt)
          }
          return true
        case 'PushSucceeded':
          if (model.push._tag === 'in-flight' && model.push.operationId === message.operationId) {
            model = {
              ...model,
              push: { _tag: 'idle', queued: model.push.queued },
            }
            yield* startProviderPush()
          }
          return true
        case 'PushFailed':
          if (model.push._tag !== 'in-flight' || model.push.operationId !== message.operationId) return true
          if (message.error._tag === 'ServerAheadError') {
            // Pulling first will either confirm or rebase these events. Keep them queued, but do not retry the same
            // stale batch until the pull has established the new durable plan.
            model = {
              ...model,
              push: {
                _tag: 'awaiting-pull',
                queued: [...model.push.batch, ...model.push.queued],
              },
            }
            return true
          }
          if (message.error._tag === 'BackendIdMismatchError')
            return yield* handleBackendMismatch(message.error, 'push')
          const retryId = allocateOperationId()
          const attempt = model.push.attempt + 1
          model = {
            ...model,
            push: {
              _tag: 'retry-wait',
              retryId,
              attempt,
              batch: model.push.batch,
              queued: model.push.queued,
            },
          }
          yield* fork(
            Effect.sleep(Duration.millis(retryDelay(attempt))).pipe(
              Effect.andThen(send({ _tag: 'PushRetryElapsed', retryId })),
            ),
          )
          return true
        case 'PushRetryElapsed':
          if (model.push._tag === 'retry-wait' && model.push.retryId === message.retryId) {
            const { attempt, batch, queued } = model.push
            yield* runPushOperation({ attempt, batch, queued })
          }
          return true
        default:
          return casesHandled(message)
      }
    })

  const run = Effect.gen(function* () {
    // This is the only general message consumer and therefore the single owner of transition ordering.
    let running = true
    while (running === true) {
      const message = yield* Queue.take(mailbox)
      const exit = yield* handleMessage(message).pipe(Effect.exit)
      if (Exit.isFailure(exit) === true) {
        running = yield* stop({ lifecycle: 'failed', error: Cause.squash(exit.cause), notify: true })
      } else {
        running = exit.value
      }
    }
    yield* Queue.shutdown(mailbox)
  })

  const push: Service['push'] = (events) =>
    Effect.gen(function* () {
      if (events.length === 0) return
      const requestId = yield* Ref.modify(nextLocalRequestId, (id) => [id, id + 1])
      const deferred = yield* Deferred.make<void, RejectedPushError>()
      // Register the acknowledgement before waiting for boot. Shutdown can then interrupt every admitted caller,
      // including one that has not reached the mailbox yet.
      const admitted = yield* Ref.modify(localRequests, (registry) => {
        if (registry._tag === 'closed') return [false, registry]
        return [
          true,
          {
            _tag: 'open' as const,
